+import { verifySignedToken, SessionData } from "./session-token.ts";
+
+// Example: How an edge worker would validate a session
+export const authenticateRequest = (sessionToken: string): SessionData | null => {
+  // The edge worker receives the token (e.g., from Authorization header)
+  // and validates it cryptographically without any database or API calls
+  return verifySignedToken(sessionToken);
+};
+
+// Example: Edge worker handling a read API request
+export const handleReadAPIRequest = (
+  sessionToken: string,
+  requestBody: unknown,
+): { status: number; body: unknown } => {
+  const session = authenticateRequest(sessionToken);
+
+  if (!session) {
+    return { status: 401, body: { error: "Unauthorized" } };
+  }
+
+  // At this point, the edge worker has validated the session
+  // without any database or network access beyond the request itself
+  return { status: 200, body: { userId: session.userId, requestBody } };
+};
