--- /dev/null
+++ b/src/session-token.ts
@@ -0,0 +1,63 @@
+import { createHmac } from "crypto";
+
+export interface SessionData {
+  id: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+}
+
+const SECRET_KEY = process.env.SESSION_TOKEN_SECRET || "default-secret-change-in-production";
+const TOKEN_DELIMITER = ".";
+const SIGNATURE_ALGORITHM = "sha256";
+
+export const createSignedToken = (session: {
+  id: string;
+  userId: string;
+}): string => {
+  const now = Date.now();
+  const expiresAt = now + 24 * 60 * 60 * 1000; // 24 hours
+
+  const data: SessionData = {
+    id: session.id,
+    userId: session.userId,
+    issuedAt: now,
+    expiresAt,
+  };
+
+  const payload = JSON.stringify(data);
+  const signature = createHmac(SIGNATURE_ALGORITHM, SECRET_KEY)
+    .update(payload)
+    .digest("hex");
+
+  return `${Buffer.from(payload).toString("base64")}${TOKEN_DELIMITER}${signature}`;
+};
+
+export const verifySignedToken = (token: string): SessionData | null => {
+  const parts = token.split(TOKEN_DELIMITER);
+  if (parts.length !== 2) return null;
+
+  const [encodedPayload, signature] = parts;
+
+  try {
+    const payload = Buffer.from(encodedPayload, "base64").toString("utf-8");
+    const expectedSignature = createHmac(SIGNATURE_ALGORITHM, SECRET_KEY)
+      .update(payload)
+      .digest("hex");
+
+    if (signature !== expectedSignature) {
+      return null;
+    }
+
+    const data = JSON.parse(payload) as SessionData;
+
+    // Check expiration
+    if (data.expiresAt < Date.now()) {
+      return null;
+    }
+
+    return data;
+  } catch {
+    return null;
+  }
+};
